const Parser = require('rss-parser');
const axios = require('axios');
const Anthropic = require('@anthropic-ai/sdk');
const fs = require('fs').promises;

const apiKey = process.env.ANTHROPIC_API_KEY;
if (!apiKey) {
  throw new Error('ANTHROPIC_API_KEY not set');
}

const anthropic = new Anthropic({ apiKey });
const parser = new Parser();

async function main() {
  // 1. Fetch the RSS feed
  const feedUrl = 'https://hnrss.org/frontpage';
  console.log('Fetching feed:', feedUrl);

  const feed = await parser.parseURL(feedUrl);
  const topStory = feed.items[0];

  console.log('Top story:', topStory.title);
  console.log('Link:', topStory.link);
}

// 2. Fetch the full article
console.log('Fetching article content...');
const articleResponse = await axios.get(topStory.link);
const articleHtml = articleResponse.data;

// In production: parse HTML to extract article text
// For now: send the whole page to Claude

// 3. Ask Claude to summarize
console.log('Asking Claude for summary...');
const response = await anthropic.messages.create({
  model: 'claude-sonnet-4.6',
  max_tokens: 1000,
  messages: [{
    role: 'user',
    content: `You are a news summarizer. Read this article and give me a 3-sentence summary focusing on what matters.\n\nArticle:\n${articleHtml}`
  }]
});

const summary = response.content[0].text;
console.log('Summary received:', summary);

  // 4. Save the summary
  const output = `# Today's Top Story

Date: ${new Date().toLocaleDateString()}

## ${topStory.title}

Link: ${topStory.link}

### Summary

${summary}
`;

  await fs.writeFile('today-news.md', output, 'utf-8');
  console.log('✓ Summary saved to today-news.md');
}

main().catch(err => {
  console.error('Error:', err);
  process.exit(1);
});
